class MoveWord {
  public void solve(char[] arr, String word) {
    int seeker = 0, writer = 0;
    int i = 0;
    while (seeker < arr.length) {
      if (i < word.length() && arr[seeker] == word.charAt(i)) {
        seeker++;
        i++;
      } else {
        arr[writer] = arr[seeker];
        seeker++;
        writer++;
      }
    }
    for (char c : word.toCharArray()) {
      arr[writer] = c;
      writer++;
    }
  }
}

